//! Routine execution engine.//!//! Handles loading routines, checking triggers, enforcing guardrails,//! and executing both lightweight (single LLM call) and full-job routines.//!//! The engine runs two independent loops://! - A **cron ticker** that polls the DB every N seconds for due cron routines//! - An **event matcher** called synchronously from the agent main loop//!//! Lightweight routines execute inline (single LLM call, no scheduler slot).//! Full-job routines are delegated to the existing `Scheduler`.use std::sync::Arc;use std::sync::atomic::{AtomicUsize, Ordering};use std::time::Duration;use chrono::Utc;use regex::Regex;use tokio::sync::{RwLock, mpsc};use uuid::Uuid;use crate::agent::Scheduler;use crate::agent::routine::{    NotifyConfig, Routine, RoutineAction, RoutineRun, RunStatus, Trigger, next_cron_fire,};use crate::channels::{IncomingMessage, OutgoingResponse};use crate::config::RoutineConfig;use crate::context::JobContext;use crate::db::Database;use crate::error::RoutineError;use crate::llm::{    ChatMessage, CompletionRequest, FinishReason, LlmProvider, ToolCall, ToolCompletionRequest,};use crate::safety::SafetyLayer;use crate::tools::{    ApprovalContext, ApprovalRequirement, ToolError, ToolRegistry, prepare_tool_params,};use crate::workspace::Workspace;enum EventMatcher {    Message { routine: Routine, regex: Regex },    System { routine: Routine },}/// The routine execution engine.pub struct RoutineEngine {    config: RoutineConfig,    store: Arc<dyn Database>,    llm: Arc<dyn LlmProvider>,    workspace: Arc<Workspace>,    /// Sender for notifications (routed to channel manager).    notify_tx: mpsc::Sender<OutgoingResponse>,    /// Currently running routine count (across all routines).    running_count: Arc<AtomicUsize>,    /// Cached matchers for all event-driven routines.    event_cache: Arc<RwLock<Vec<EventMatcher>>>,    /// Scheduler for dispatching jobs (FullJob mode).    scheduler: Option<Arc<Scheduler>>,    /// Tool registry for lightweight routine tool execution.    tools: Arc<ToolRegistry>,    /// Safety layer for tool output sanitization.    safety: Arc<SafetyLayer>,}impl RoutineEngine {    #[allow(clippy::too_many_arguments)]    pub fn new(        config: RoutineConfig,        store: Arc<dyn Database>,        llm: Arc<dyn LlmProvider>,        workspace: Arc<Workspace>,        notify_tx: mpsc::Sender<OutgoingResponse>,        scheduler: Option<Arc<Scheduler>>,        tools: Arc<ToolRegistry>,        safety: Arc<SafetyLayer>,    ) -> Self {        Self {            config,            store,            llm,            workspace,            notify_tx,            running_count: Arc::new(AtomicUsize::new(0)),            event_cache: Arc::new(RwLock::new(Vec::new())),            scheduler,            tools,            safety,        }    }    /// Refresh the in-memory event trigger cache from DB.    pub async fn refresh_event_cache(&self) {        match self.store.list_event_routines().await {            Ok(routines) => {                let mut cache = Vec::new();                for routine in routines {                    match &routine.trigger {                        Trigger::Event { pattern, .. } => {                            // Use RegexBuilder with size limit to prevent ReDoS                            // from user-supplied patterns (issue #825).                            match regex::RegexBuilder::new(pattern)                                .size_limit(64 * 1024) // 64KB compiled size limit                                .build()                            {                                Ok(re) => cache.push(EventMatcher::Message {                                    routine: routine.clone(),                                    regex: re,                                }),                                Err(e) => {                                    tracing::warn!(                                        routine = %routine.name,                                        "Invalid or too complex event regex '{}': {}",                                        pattern, e                                    );                                }                            }                        }                        Trigger::SystemEvent { .. } => {                            cache.push(EventMatcher::System {                                routine: routine.clone(),                            });                        }                        _ => {}                    }                }                let count = cache.len();                *self.event_cache.write().await = cache;                tracing::trace!("Refreshed event cache: {} routines", count);            }            Err(e) => {                tracing::error!("Failed to refresh event cache: {}", e);            }        }    }    /// Check incoming message against event triggers. Returns number of routines fired.    ///    /// Called synchronously from the main loop after handle_message(). The actual    /// execution is spawned async so this returns quickly.    pub async fn check_event_triggers(&self, message: &IncomingMessage) -> usize {        let cache = self.event_cache.read().await;        let mut fired = 0;        // Collect routine IDs for batch query        let routine_ids: Vec<Uuid> = cache            .iter()            .filter_map(|matcher| match matcher {                EventMatcher::Message { routine, .. } => Some(routine.id),                EventMatcher::System { .. } => None,            })            .collect();        if routine_ids.is_empty() {            return 0;        }        // Single batch query instead of N queries        let concurrent_counts = match self            .store            .count_running_routine_runs_batch(&routine_ids)            .await        {            Ok(counts) => counts,            Err(e) => {                tracing::error!("Failed to batch-load concurrent counts: {}", e);                return 0;            }        };        for matcher in cache.iter() {            let (routine, re) = match matcher {                EventMatcher::Message { routine, regex } => (routine, regex),                EventMatcher::System { .. } => continue,            };            // Channel filter            if let Trigger::Event {                channel: Some(ch), ..            } = &routine.trigger                && ch != &message.channel            {                continue;            }            // Regex match            if !re.is_match(&message.content) {                continue;            }            // Cooldown check            if !self.check_cooldown(routine) {                tracing::trace!(routine = %routine.name, "Skipped: cooldown active");                continue;            }            // Concurrent run check (using batch-loaded counts)            let running_count = concurrent_counts.get(&routine.id).copied().unwrap_or(0);            if running_count >= routine.guardrails.max_concurrent as i64 {                tracing::trace!(routine = %routine.name, "Skipped: max concurrent reached");                continue;            }            // Global capacity check            if self.running_count.load(Ordering::Relaxed) >= self.config.max_concurrent_routines {                tracing::warn!(routine = %routine.name, "Skipped: global max concurrent reached");                continue;            }            let detail = truncate(&message.content, 200);            self.spawn_fire(routine.clone(), "event", Some(detail));            fired += 1;        }        fired    }    /// Emit a structured event to system-event routines.    ///    /// Returns the number of routines that were fired.    pub async fn emit_system_event(        &self,        source: &str,        event_type: &str,        payload: &serde_json::Value,        user_id: Option<&str>,    ) -> usize {        let cache = self.event_cache.read().await;        let mut fired = 0;        // Collect routine IDs for batch query        let routine_ids: Vec<Uuid> = cache            .iter()            .filter_map(|matcher| match matcher {                EventMatcher::System { routine } => Some(routine.id),                EventMatcher::Message { .. } => None,            })            .collect();        if routine_ids.is_empty() {            return 0;        }        // Single batch query instead of N queries        let concurrent_counts = match self            .store            .count_running_routine_runs_batch(&routine_ids)            .await        {            Ok(counts) => counts,            Err(e) => {                tracing::error!(                    "Failed to batch-load concurrent counts for system events: {}",                    e                );                return 0;            }        };        for matcher in cache.iter() {            let routine = match matcher {                EventMatcher::System { routine } => routine,                EventMatcher::Message { .. } => continue,            };            let Trigger::SystemEvent {                source: expected_source,                event_type: expected_event,                filters,            } = &routine.trigger            else {                continue;            };            if !expected_source.eq_ignore_ascii_case(source)                || !expected_event.eq_ignore_ascii_case(event_type)            {                continue;            }            if let Some(uid) = user_id                && routine.user_id != uid            {                continue;            }            let mut matched = true;            for (key, expected) in filters {                let Some(actual) = payload                    .get(key)                    .and_then(crate::agent::routine::json_value_as_filter_string)                else {                    tracing::debug!(routine = %routine.name, filter_key = %key, "Filter key not found in payload");                    matched = false;                    break;                };                if !actual.eq_ignore_ascii_case(expected) {                    matched = false;                    break;                }            }            if !matched {                continue;            }            if !self.check_cooldown(routine) {                tracing::debug!(routine = %routine.name, "Skipped: cooldown active");                continue;            }            // Concurrent run check (using batch-loaded counts)            let running_count = concurrent_counts.get(&routine.id).copied().unwrap_or(0);            if running_count >= routine.guardrails.max_concurrent as i64 {                tracing::debug!(routine = %routine.name, "Skipped: max concurrent reached");                continue;            }            if self.running_count.load(Ordering::Relaxed) >= self.config.max_concurrent_routines {                tracing::warn!(routine = %routine.name, "Skipped: global max concurrent reached");                continue;            }            let detail = truncate(&format!("{source}:{event_type}"), 200);            self.spawn_fire(routine.clone(), "system_event", Some(detail));            fired += 1;        }        fired    }    /// Check all due cron routines and fire them. Called by the cron ticker.    pub async fn check_cron_triggers(&self) {        let routines = match self.store.list_due_cron_routines().await {            Ok(r) => r,            Err(e) => {                tracing::error!("Failed to load due cron routines: {}", e);                return;            }        };        for routine in routines {            if self.running_count.load(Ordering::Relaxed) >= self.config.max_concurrent_routines {                tracing::warn!("Global max concurrent routines reached, skipping remaining");                break;            }            if !self.check_cooldown(&routine) {                continue;            }            if !self.check_concurrent(&routine).await {                continue;            }            let detail = if let Trigger::Cron { ref schedule, .. } = routine.trigger {                Some(schedule.clone())            } else {                None            };            self.spawn_fire(routine, "cron", detail);        }    }    /// Fire a routine manually (from tool call or CLI).    ///    /// Bypasses cooldown checks (those only apply to cron/event triggers).    /// Still enforces enabled check and concurrent run limit.    pub async fn fire_manual(        &self,        routine_id: Uuid,        user_id: Option<&str>,    ) -> Result<Uuid, RoutineError> {        let routine = self            .store            .get_routine(routine_id)            .await            .map_err(|e| RoutineError::Database {                reason: e.to_string(),            })?            .ok_or(RoutineError::NotFound { id: routine_id })?;        // Enforce ownership when a user_id is provided (gateway calls).        if let Some(uid) = user_id            && routine.user_id != uid        {            return Err(RoutineError::NotAuthorized { id: routine_id });        }        if !routine.enabled {            return Err(RoutineError::Disabled {                name: routine.name.clone(),            });        }        if !self.check_concurrent(&routine).await {            return Err(RoutineError::MaxConcurrent {                name: routine.name.clone(),            });        }        let run_id = Uuid::new_v4();        let run = RoutineRun {            id: run_id,            routine_id: routine.id,            trigger_type: "manual".to_string(),            trigger_detail: None,            started_at: Utc::now(),            completed_at: None,            status: RunStatus::Running,            result_summary: None,            tokens_used: None,            job_id: None,            created_at: Utc::now(),        };        if let Err(e) = self.store.create_routine_run(&run).await {            return Err(RoutineError::Database {                reason: format!("failed to create run record: {e}"),            });        }        // Execute inline for manual triggers (caller wants to wait)        let engine = EngineContext {            config: self.config.clone(),            store: self.store.clone(),            llm: self.llm.clone(),            workspace: self.workspace.clone(),            notify_tx: self.notify_tx.clone(),            running_count: self.running_count.clone(),            scheduler: self.scheduler.clone(),            tools: self.tools.clone(),            safety: self.safety.clone(),        };        tokio::spawn(async move {            execute_routine(engine, routine, run).await;        });        Ok(run_id)    }    /// Spawn a fire in a background task.    fn spawn_fire(&self, routine: Routine, trigger_type: &str, trigger_detail: Option<String>) {        let run = RoutineRun {            id: Uuid::new_v4(),            routine_id: routine.id,            trigger_type: trigger_type.to_string(),            trigger_detail,            started_at: Utc::now(),            completed_at: None,            status: RunStatus::Running,            result_summary: None,            tokens_used: None,            job_id: None,            created_at: Utc::now(),        };        let engine = EngineContext {            config: self.config.clone(),            store: self.store.clone(),            llm: self.llm.clone(),            workspace: self.workspace.clone(),            notify_tx: self.notify_tx.clone(),            running_count: self.running_count.clone(),            scheduler: self.scheduler.clone(),            tools: self.tools.clone(),            safety: self.safety.clone(),        };        // Record the run in DB, then spawn execution        let store = self.store.clone();        tokio::spawn(async move {            if let Err(e) = store.create_routine_run(&run).await {                tracing::error!(routine = %routine.name, "Failed to record run: {}", e);                return;            }            execute_routine(engine, routine, run).await;        });    }    fn check_cooldown(&self, routine: &Routine) -> bool {        if let Some(last_run) = routine.last_run_at {            let elapsed = Utc::now().signed_duration_since(last_run);            let cooldown = chrono::Duration::from_std(routine.guardrails.cooldown)                .unwrap_or(chrono::Duration::seconds(300));            if elapsed < cooldown {                return false;            }        }        true    }    async fn check_concurrent(&self, routine: &Routine) -> bool {        match self.store.count_running_routine_runs(routine.id).await {            Ok(count) => count < routine.guardrails.max_concurrent as i64,            Err(e) => {                tracing::error!(                    routine = %routine.name,                    "Failed to check concurrent runs: {}", e                );                false            }        }    }}/// Shared context passed to the execution function.struct EngineContext {    config: RoutineConfig,    store: Arc<dyn Database>,    llm: Arc<dyn LlmProvider>,    workspace: Arc<Workspace>,    notify_tx: mpsc::Sender<OutgoingResponse>,    running_count: Arc<AtomicUsize>,    scheduler: Option<Arc<Scheduler>>,    tools: Arc<ToolRegistry>,    safety: Arc<SafetyLayer>,}/// Execute a routine run. Handles both lightweight and full_job modes.async fn execute_routine(ctx: EngineContext, routine: Routine, run: RoutineRun) {    // Increment running count (atomic: survives panics in the execution below)    ctx.running_count.fetch_add(1, Ordering::Relaxed);    let result = match &routine.action {        RoutineAction::Lightweight {            prompt,            context_paths,            max_tokens,            use_tools,            max_tool_rounds,        } => {            execute_lightweight(                &ctx,                &routine,                prompt,                context_paths,                *max_tokens,                *use_tools,                *max_tool_rounds,            )            .await        }        RoutineAction::FullJob {            title,            description,            max_iterations,            tool_permissions,        } => {            execute_full_job(                &ctx,                &routine,                &run,                title,                description,                *max_iterations,                tool_permissions,            )            .await        }    };    // Decrement running count    ctx.running_count.fetch_sub(1, Ordering::Relaxed);    // Process result    let (status, summary, tokens) = match result {        Ok(execution) => execution,        Err(e) => {            tracing::error!(routine = %routine.name, "Execution failed: {}", e);            (RunStatus::Failed, Some(e.to_string()), None)        }    };    // Complete the run record    if let Err(e) = ctx        .store        .complete_routine_run(run.id, status, summary.as_deref(), tokens)        .await    {        tracing::error!(routine = %routine.name, "Failed to complete run record: {}", e);    }    // Update routine runtime state    let now = Utc::now();    let next_fire = if let Trigger::Cron {        ref schedule,        ref timezone,    } = routine.trigger    {        next_cron_fire(schedule, timezone.as_deref()).unwrap_or(None)    } else {        None    };    let new_failures = if status == RunStatus::Failed {        routine.consecutive_failures + 1    } else {        0    };    if let Err(e) = ctx        .store        .update_routine_runtime(            routine.id,            now,            next_fire,            routine.run_count + 1,            new_failures,            &routine.state,        )        .await    {        tracing::error!(routine = %routine.name, "Failed to update runtime state: {}", e);    }    // Persist routine result to its dedicated conversation thread    let thread_id = match ctx        .store        .get_or_create_routine_conversation(routine.id, &routine.name, &routine.user_id)        .await    {        Ok(conv_id) => {            tracing::debug!(                routine = %routine.name,                routine_id = %routine.id,                conversation_id = %conv_id,                "Resolved routine conversation thread"            );            // Record the run result as a conversation message            let msg = match (&summary, status) {                (Some(s), _) => format!("[{}] {}: {}", run.trigger_type, status, s),                (None, _) => format!("[{}] {}", run.trigger_type, status),            };            if let Err(e) = ctx                .store                .add_conversation_message(conv_id, "assistant", &msg)                .await            {                tracing::error!(routine = %routine.name, "Failed to persist routine message: {}", e);            }            Some(conv_id.to_string())        }        Err(e) => {            tracing::error!(routine = %routine.name, "Failed to get routine conversation: {}", e);            None        }    };    // Send notifications based on config    send_notification(        &ctx.notify_tx,        &routine.notify,        &routine.name,        status,        summary.as_deref(),        thread_id.as_deref(),    )    .await;}/// Sanitize a routine name for use in workspace paths./// Only keeps alphanumeric, dash, and underscore characters; replaces everything else.fn sanitize_routine_name(name: &str) -> String {    name.chars()        .map(|c| {            if c.is_ascii_alphanumeric() || c == '-' || c == '_' {                c            } else {                '_'            }        })        .collect()}/// Execute a full-job routine by dispatching to the scheduler.////// Fire-and-forget: creates a job via `Scheduler::dispatch_job` (which handles/// creation, metadata, persistence, and scheduling), links the routine run to/// the job, and returns immediately. The job runs independently via the/// existing Worker/Scheduler with full tool access.